1	// Fault-injection shims for the regression-test build of envelopefile.
2	//
3	// This file is linked together with src/main.cpp into the separate
4	// `envelopefile_testable` binary using the linker's --wrap option, so every
5	// open/write/fsync/close call made by the product code is routed through the
6	// __wrap_* functions below. The production binary is completely unaffected.
7	//
8	// Injection is controlled entirely through environment variables so the test
9	// driver can select a scenario per process run:
10	//
11	//   EF_TEST_TARGET          Only inject faults for this exact path. When
12	//                           unset, any file created with O_CREAT|O_EXCL is
13	//                           considered the key file under test.
14	//   EF_TEST_FAIL_WRITE=1    write() on the key file fails with EIO.
15	//   EF_TEST_PARTIAL_WRITE=N write() on the key file returns at most N bytes
16	//                           per call (the caller must loop to complete).
17	//   EF_TEST_FAIL_FSYNC=1    fsync() on the key file fails with EIO.
18	//   EF_TEST_FAIL_CLOSE=1    close() on the key file reports EIO (the
19	//                           descriptor is still really closed, matching the
20	//                           POSIX guarantee that close() releases the fd).
21	//   EF_TEST_FAIL_FCHMOD=1   fchmod() on the key file fails with EPERM, so the
22	//                           0600 permission guarantee cannot be established.
23	//
24	// For deterministic coverage of the write loop itself, a per-call script can
25	// be supplied:
26	//
27	//   EF_TEST_WRITE_SCRIPT=t1,t2,...
28	//                           Each token describes the outcome of one write()
29	//                           call on the key file, consumed in order; once the
30	//                           list is exhausted every further call succeeds
31	//                           normally. Tokens:
32	//                             ok    - write the whole requested buffer
33	//                             N     - short write: at most N (decimal) bytes
34	//                             intr  - fail with EINTR, no bytes written
35	//                             eio   - fail irrecoverably with EIO
36	//                             zero  - return 0 with bytes still pending
37	//
38	//   EF_TEST_WRITE_LOG=path  Record what the write loop actually did, so the
39	//                           test driver can prove byte continuity across
40	//                           retries. On the first key-file write the original
41	//                           32-byte key is snapshotted; every subsequent call
42	//                           is checked to advance from the current offset with
43	//                           a buffer that is a slice of that same snapshot
44	//                           (i.e. the key is neither regenerated, duplicated,
45	//                           nor dropped). Every call is also checked to pass a
46	//                           pointer INTO the exact buffer RAND_bytes filled
47	//                           (at the current offset), so the bytes that reach
48	//                           the file are provably the ones the later
49	//                           OPENSSL_cleanse wipes — not a copy living
50	//                           elsewhere. The file receives one line:
51	//                             VERIFY <64 lowercase hex digits>
52	//                           followed by one line per write() call:
53	//                             CALL <offset> <requested> <returned> [<errno>]
54	//                           (the errno field is only present when returned is
55	//                           -1). A continuity violation is recorded as a
56	//                             VERIFY-FAILED <reason>
57	//                           line and aborts the process, since it means the
58	//                           product code violated its own write contract.
59	//
60	// The secure random source can be made to fail deterministically:
61	//
62	//   EF_TEST_FAIL_RAND=1       RAND_bytes reports failure (returns 0).
63	//   EF_TEST_RAND_PARTIAL=N    before failing, N marker bytes (0xA5) are
64	//                             written into the caller's key buffer,
65	//                             simulating a CSPRNG that dies mid-fill. The
66	//                             marker lets the test driver prove the partial
67	//                             data is neither saved nor leaked.
68	//   EF_TEST_RAND_ERROR_DETAIL=1
69	//                             leave a descriptive OpenSSL error on the
70	//                             thread's error queue so the failure carries
71	//                             detail text; when unset the queue is cleared
72	//                             instead, exercising the no-detail message.
73	//
74	// Key-buffer lifecycle events are recorded when requested:
75	//
76	//   EF_TEST_KEY_LOG=path      one line per event:
77	//                               RAND <requested> partial=<N> result=<ok|fail>
78	//                               CLEANSED-KEY <len>
79	//                               CLEANSE-STATE writes=<N> keyfd=<open|closed>
80	//                             The CLEANSED-KEY line is emitted when the
81	//                             buffer previously handed to RAND_bytes is
82	//                             wiped via OPENSSL_cleanse, proving the key
83	//                             (including any partial bytes) does not survive
84	//                             the operation in memory. It is followed by a
85	//                             CLEANSE-STATE line capturing how many key bytes
86	//                             had been written and whether the key-file
87	//                             descriptor was already closed at that moment,
88	//                             so the test driver can prove the wipe happened
89	//                             only after the save was complete (never before,
90	//                             which would save wiped data).
91	//
92	// Only the file descriptor opened for the key file is instrumented; all
93	// other I/O (stdout, stderr, OpenSSL internals, the log file itself) passes
94	// through untouched.
95	
96	#include <openssl/err.h>
97	#include <openssl/opensslv.h>
98	#include <openssl/rand.h>
