112	// Real libc/libcrypto entry points provided by the --wrap linker mechanism.
113	int __real_open(const char* path, int flags, ...);
114	int __real_fchmod(int fd, mode_t mode);
115	ssize_t __real_write(int fd, const void* buffer, size_t count);
116	int __real_fsync(int fd);
