182	void logVerifyHeader(const unsigned char* buffer) {
183	    constexpr std::size_t kPrefix = 7;  // strlen("VERIFY ")
184	    char line[kPrefix + 2 * kKeyBytes + 1];
185	    char* out = line;
186	    std::strcpy(out, "VERIFY ");
187	    out += 7;
188	    static const char hex[] = "0123456789abcdef";
189	    for (std::size_t i = 0; i < kKeyBytes; ++i) {
190	        *out++ = hex[buffer[i] >> 4];
191	        *out++ = hex[buffer[i] & 0x0f];
