216	// On the first key-file write, snapshot the key; afterwards confirm that the
217	// caller resumes exactly at the acknowledged offset and presents the matching
218	// slice of the same key. Every call must also pass a pointer into the very
219	// buffer RAND_bytes filled (at the current offset): the bytes reaching the
220	// file are then provably the ones OPENSSL_cleanse later wipes, not an
221	// unwiped copy. Any mismatch is a product-code defect: abort so the
222	// regression run can never pass on a silently regenerated/garbled key.
223	void verifyIncomingBuffer(const void* buffer, std::size_t count) {
224	    if (std::getenv("EF_TEST_WRITE_LOG") == nullptr) {
225	        return;
226	    }
227	    const auto* bytes = static_cast<const unsigned char*>(buffer);
228	    if (g_randBuf != nullptr && bytes != g_randBuf + g_progress) {
229	        logVerifyFailed("write buffer is not the buffer filled by RAND_bytes");
230	        std::abort();
231	    }
232	    if (!g_haveSnapshot) {
233	        if (count != kKeyBytes) {
234	            logVerifyFailed("first write did not carry the whole 32-byte key");
235	            std::abort();
236	        }
237	        std::memcpy(g_keySnapshot, bytes, kKeyBytes);
238	        g_haveSnapshot = true;
239	        logVerifyHeader(g_keySnapshot);
240	        return;
241	    }
242	    if (g_progress > kKeyBytes) {
243	        logVerifyFailed("offset past end of key");
244	        std::abort();
245	    }
246	    const std::size_t remaining = kKeyBytes - g_progress;
247	    if (count != remaining) {
248	        logVerifyFailed("write length does not match the bytes still pending");
249	        std::abort();
250	    }
251	    if (std::memcmp(g_keySnapshot + g_progress, bytes, remaining) != 0) {
252	        logVerifyFailed("buffer is not the same key (key was regenerated?)");
253	        std::abort();
254	    }
