262	// Outcome of one scripted write() call.
263	enum class WriteOutcome {
264	    kPass,       // behave as the real syscall with the given count
265	    kShort,      // behave as the real syscall but cap the count
266	    kEintr,      // report a recoverable interrupt, nothing written
267	    kEio,        // report an irrecoverable I/O error
268	    kZero,       // report zero bytes with data still pending
269	};
270	
271	struct ScriptedCall {
272	    WriteOutcome outcome;
273	    long limit;  // valid for kShort
274	};
275	
276	// Parse the next EF_TEST_WRITE_SCRIPT token. Returns false once the script is
277	// exhausted (the caller should then behave normally).
278	bool nextScriptedCall(ScriptedCall& call) {
279	    static char script[512];
280	    static bool initialized = false;
281	    static char* saveptr = nullptr;
282	
283	    if (!initialized) {
284	        const char* raw = std::getenv("EF_TEST_WRITE_SCRIPT");
285	        if (raw == nullptr) {
286	            script[0] = '\0';
287	        } else {
288	            std::strncpy(script, raw, sizeof(script) - 1);
289	            script[sizeof(script) - 1] = '\0';
290	        }
291	        saveptr = script;
292	        initialized = true;
293	    }
294	
295	    char* token = ::strtok_r(nullptr, ",", &saveptr);
296	    if (token == nullptr) {
297	        return false;
298	    }
299	    if (std::strcmp(token, "ok") == 0) {
300	        call.outcome = WriteOutcome::kPass;
301	    } else if (std::strcmp(token, "intr") == 0) {
302	        call.outcome = WriteOutcome::kEintr;
303	    } else if (std::strcmp(token, "eio") == 0) {
304	        call.outcome = WriteOutcome::kEio;
305	    } else if (std::strcmp(token, "zero") == 0) {
306	        call.outcome = WriteOutcome::kZero;
307	    } else {
308	        char* end = nullptr;
309	        long limit = std::strtol(token, &end, 10);
310	        if (end != token && *end == '\0' && limit > 0) {
311	            call.outcome = WriteOutcome::kShort;
312	            call.limit = limit;
313	        } else {
314	            // An unknown token is a test-script bug: fail loudly rather than
315	            // silently behave as a normal write.
316	            std::fprintf(stderr,
317	                         "envelopefile_testable: invalid write script token "
318	                         "'%s'\n", token);
319	            call.outcome = WriteOutcome::kEio;
320	        }
321	    }
322	    return true;
323	}
