327	int __wrap_open(const char* path, int flags, ...) {
328	    mode_t mode = 0;
329	    if ((flags & O_CREAT) != 0) {
330	        va_list args;
331	        va_start(args, flags);
332	        mode = static_cast<mode_t>(va_arg(args, int));
