352	ssize_t __wrap_write(int fd, const void* buffer, size_t count) {
353	    if (!isKeyFd(fd)) {
354	        return __real_write(fd, buffer, count);
355	    }
356	
357	    verifyIncomingBuffer(buffer, count);
358	
359	    const size_t requested = count;  // caller's original length for the log
360	    ScriptedCall call;
361	    const bool scripted = nextScriptedCall(call);
362	    if (scripted) {
363	        switch (call.outcome) {
364	            case WriteOutcome::kEintr:
365	                logCall(g_progress, requested, -1, EINTR);
366	                errno = EINTR;
367	                return -1;
368	            case WriteOutcome::kEio:
369	                logCall(g_progress, requested, -1, EIO);
370	                errno = EIO;
371	                return -1;
372	            case WriteOutcome::kZero:
373	                logCall(g_progress, requested, 0, 0);
374	                errno = 0;
375	                return 0;
376	            case WriteOutcome::kShort:
377	                if (count > static_cast<size_t>(call.limit)) {
378	                    count = static_cast<size_t>(call.limit);
379	                }
380	                break;
381	            case WriteOutcome::kPass:
382	                break;
383	        }
384	    } else {
385	        // Legacy single-knob injection, kept for the existing regressions.
386	        if (envFlagSet("EF_TEST_FAIL_WRITE")) {
387	            logCall(g_progress, requested, -1, EIO);
388	            errno = EIO;
389	            return -1;
390	        }
391	        const char* chunk = std::getenv("EF_TEST_PARTIAL_WRITE");
392	        if (chunk != nullptr) {
393	            const long limit = std::atol(chunk);
394	            if (limit > 0 && count > static_cast<size_t>(limit)) {
395	                count = static_cast<size_t>(limit);
396	            }
397	        }
398	    }
399	
400	    ssize_t result = __real_write(fd, buffer, count);
401	    logCall(g_progress, requested, result, errno);
402	    if (result > 0) {
403	        g_progress += static_cast<std::size_t>(result);
404	    }
405	    return result;
406	}
