408	int __wrap_fsync(int fd) {
409	    if (isKeyFd(fd) && envFlagSet("EF_TEST_FAIL_FSYNC")) {
410	        errno = EIO;
411	        return -1;
412	    }
413	    return __real_fsync(fd);
414	}
