416	int __wrap_close(int fd) {
417	    const bool wasKeyFd = isKeyFd(fd);
418	    const int result = __real_close(fd);
419	    if (wasKeyFd) {
420	        g_keyFd = -1;
421	        if (envFlagSet("EF_TEST_FAIL_CLOSE")) {
422	            // The descriptor is already closed for real; only the reported
423	            // status is faked, mirroring a genuine close(2) failure.
424	            errno = EIO;
425	            return -1;
426	        }
427	    }
428	    return result;
429	}
430	
431	int __wrap_RAND_bytes(unsigned char* buf, int num) {
432	    if (!envFlagSet("EF_TEST_FAIL_RAND")) {
433	        const int result = __real_RAND_bytes(buf, num);
434	        if (result == 1) {
435	            g_randBuf = buf;
436	            g_randBufSize = num;
437	            char line[96];
438	            std::snprintf(line, sizeof(line),
439	                          "RAND %d partial=0 result=ok", num);
440	            logKeyLine(line);
441	        }
442	        return result;
443	    }
444	
445	    g_randBuf = buf;
446	    g_randBufSize = num;
447	
448	    // Simulate a CSPRNG that wrote some bytes before dying: the caller must
449	    // not mistake the partial fill for a valid key.
450	    long partial = 0;
451	    const char* raw = std::getenv("EF_TEST_RAND_PARTIAL");
452	    if (raw != nullptr) {
453	        partial = std::atol(raw);
454	        if (partial < 0) {
455	            partial = 0;
456	        }
457	        if (partial > num) {
458	            partial = num;
459	        }
460	    }
461	    for (long i = 0; i < partial; ++i) {
462	        buf[i] = 0xA5;
463	    }
464	
465	    // Start from an empty error queue, then optionally leave a descriptive
466	    // OpenSSL error so the "detail" and "no detail" messages are both
467	    // exercised deterministically.
468	    ERR_clear_error();
469	    if (envFlagSet("EF_TEST_RAND_ERROR_DETAIL")) {
470	#if OPENSSL_VERSION_NUMBER >= 0x30000000L
471	        ERR_raise(ERR_LIB_RAND, 0x7f);
472	#else
473	        ERR_put_error(ERR_LIB_RAND, 0, 0x7f, __FILE__, __LINE__);
474	#endif
475	    }
476	
477	    char line[96];
478	    std::snprintf(line, sizeof(line), "RAND %d partial=%ld result=fail",
479	                  num, partial);
480	    logKeyLine(line);
481	    return 0;
482	}
483	
484	void __wrap_OPENSSL_cleanse(void* ptr, size_t len) {
485	    if (ptr != nullptr && ptr == g_randBuf) {
486	        char line[96];
487	        std::snprintf(line, sizeof(line), "CLEANSED-KEY %zu", len);
488	        logKeyLine(line);
489	        // Record how far the save had progressed when the wipe happened, so
490	        // the test driver can prove a successful save was not preceded by
491	        // the wipe (which would have saved wiped data).
492	        char state[96];
493	        std::snprintf(state, sizeof(state),
494	                      "CLEANSE-STATE writes=%zu keyfd=%s",
495	                      g_progress, g_keyFd == -1 ? "closed" : "open");
496	        logKeyLine(state);
497	        // The buffer is about to be released; do not match a stale address.
498	        g_randBuf = nullptr;
499	        g_randBufSize = 0;
500	    }
501	    __real_OPENSSL_cleanse(ptr, len);
502	}
503	
504	}  // extern "C"
